import{_ as t,H as a,f as o,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"每周一起背10句 | week 06","description":"","frontmatter":{},"headers":[],"relativePath":"互联网人的英语私教课/每周一起背10句-week06.md","filePath":"互联网人的英语私教课/每周一起背10句-week06.md","lastUpdated":1779817970000}'),s={name:"互联网人的英语私教课/每周一起背10句-week06.md"};function r(i,e,n,l,m,h){return a(),o("div",null,[...e[0]||(e[0]=[p('<h1 id="每周一起背10句-week-06" tabindex="-1">每周一起背10句 | week 06 <a class="header-anchor" href="#每周一起背10句-week-06" aria-label="Permalink to &quot;每周一起背10句 | week 06&quot;">​</a></h1><p>你好，我是英语专栏的编辑阿锦，欢迎来到第6期的“每周一起背10句”。</p><p>本周我们学完了第三篇语料，并且开始阅读第四篇语料。从第四篇语料，陈老师开始带领我们用全文通读的方法来阅读文章。不知道这个方法你掌握了吗？</p><p>这周的句子都很棒，很多句子在工作中都能用得到。你可以背完之后，试试用在自己的工作场景中。话不多说，我们一起来背诵！</p><hr><p>例句1：Establishing a high level of trust among remote managers and employees starts with having good meeting rituals.</p><p>翻译：在远程工作过程中，经理和员工之间的高度信任始于一套良好的会议仪式。</p><p>例句2：Managers must lead by example, because what you do is more important than what you say.</p><p>翻译：经理们必须以身作则，因为你的行动比你的言辞更重要。</p><p>例句3：Joe left my house around 5 pm, and was hit by a car about 30 minutes later.</p><p>翻译：乔下午五点左右离开我家，大约三十分钟后就被车撞了。</p><p>例句4：While everyone does not need to be co-located all the time, there are some situations which are only really effective when a team is all together.</p><p>翻译：虽然大家不需要总在同一地点办公，但有些工作要想真正有效开展，只有把一个团队的所有人员都聚到一起。</p><p>例句5：While remote work is very appealing to some employees, it does come with some trade-offs.</p><p>翻译：虽然远程工作对一些员工来说很有吸引力，但也一定有得有失。</p><p>例句6：Trust and openness is critically important, and allows team members to recognize when someone is struggling, and help them cope, including seeking professional help.</p><p>翻译：信任和坦诚非常重要，它能让团队成员发觉有同事在挣扎，并帮助他们应对，包括寻求专业的帮助。</p><p>例句7：Pets, exercise, and getting into nature can also help improve mental well-being.</p><p>翻译：养宠物、运动和融入大自然也可以帮助改善心理健康。</p><p>例句8：Several demonstrators broke through the barriers despite warnings from the police.</p><p>翻译：几名示威者不顾警方的警告，冲破了封锁线。</p><p>例句9：It is possible that at this election some of the minority parties might succeed in breaking through into parliament.</p><p>翻译：在这次选举中，一些少数派政党有可能获得突破，赢得议会的席位。</p><p>例句10：Statistics disprove the myth that women are worse drivers than men.</p><p>翻译：统计数据驳斥了女司机不如男司机的成见。</p>',25)])])}const _=t(s,[["render",r]]);export{c as __pageData,_ as default};
